R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
mkdir -p $R/sb_mffix/prompts $R/sb_mffix/out; echo  | base64 -d > $R/sb_mffix/prompts/sb_mffix.md; echo sb_mffix >> $R/sb_queue/queue.txt; echo Q: $(cat $R/sb_queue/queue.txt | tr "\n" " ")
for t in sb_rlfix3 sb_f64fix2; do mkdir -p $R/$t; cp $R/sb_cursor_probe/AGENTS.md $R/$t/AGENTS.md; done
echo  | base64 -d > $R/sb_rlfix3/PROMPT.md; echo  | base64 -d > $R/sb_f64fix2/PROMPT.md
for t in sb_rlfix3 sb_f64fix2; do cd $R/$t && tmux new-session -d -s $t "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"; sleep 3; done
tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; tail -2 $R/sb_queue/codexq.log
